const int Xsize = 810, Ysize = 410;
int[,] delta = new int[,] {{0, -1}, {1, 0}, {0, 1}, {-1, 0}};
int turtlesCount = 0;
int turnsCached = 0;
dungeonCell[,] lab = new dungeonCell[Xsize, Ysize];
Cell exit = new Cell(0, 0);
for (int y = 0; y < Ysize + 2; y++)
{
    for (int x = 0; x < Xsize; x++)
    {
        if (y < Ysize)
        {
            switch (labirinth[y * Xsize + x])
            {
                case '#':
                    lab[x, y] = new dungeonCell(new Cell(x, y), cellType.wall, -1, null, null, null, null);
                    break;
                case 'E':
                    exit = new Cell(x, y);
                    lab[x, y] = new dungeonCell(new Cell(x, y), cellType.exit, 0, null, new bool[] { false, false, false, false }, null, null);
                    break;
                default:
                    turtlesCount++;
                    lab[x, y] = new dungeonCell(new Cell(x, y), cellType.empty, -1, null, new bool[] { false, false, false, false }, null, null);
                    break;
            }
        }
        if (y - 2 >= 0 && y - 2 < Ysize)
        {
            var temp_wall = new bool[] { false, false, false, false };
            switch (labirinth[(y - 2) * Xsize + x])
            {
                case ' ':
                    for (int u = 0; u < 4; u++)
                    {
                        if (((y - 2 + delta[u, 1] < 0 || y - 2 + delta[u, 1] >= Ysize) ||
                            (x + delta[u, 0] < 0 || x + delta[u, 0] >= Xsize)) ||
                            ((y - 2 + delta[u, 1] >= 0 && y - 2 + delta[u, 1] < Ysize) &&
                            (x + delta[u, 0] >= 0 && x + delta[u, 0] < Xsize) &&
                            (lab[x + delta[u, 0], y - 2 + delta[u, 1]].ct == cellType.wall)))// ||
                                                                                             //lab[x + delta[u, 0], y - 2 + delta[u, 1]].ct == cellType.exit)))
                        {
                            lab[x, y - 2].walls[u] = true;
                        }
                    }
                    break;
                default:
                    break;
            }
        }
    }
}
Turtles[] turtles = new Turtles[turtlesCount];
List<dungeonCell> dc = new List<dungeonCell>();
int currTurtle = 0;
for (int u = 0; u < 4; u++)
{
    if ((exit.y + delta[u, 1] >= 0 && exit.y + delta[u, 1] < Ysize) &&
        (exit.x + delta[u, 0] >= 0 && exit.x + delta[u, 0] < Xsize) &&
        lab[exit.x + delta[u, 0], exit.y + delta[u, 1]].ct == cellType.empty)
    {
        lab[exit.x + delta[u, 0], exit.y + delta[u, 1]].routeLen = 1;
        lab[exit.x + delta[u, 0], exit.y + delta[u, 1]].prevCell = lab[exit.x, exit.y];
        dc.Add(lab[exit.x + delta[u, 0], exit.y + delta[u, 1]]);
        turtles[currTurtle] = new Turtles(lab[exit.x + delta[u, 0], exit.y + delta[u, 1]], currTurtle);
        lab[exit.x + delta[u, 0], exit.y + delta[u, 1]].turtle = turtles[currTurtle];
        currTurtle++;
    }
}
while (dc.Count > 0)
{
    List<dungeonCell> tempDc = new List<dungeonCell>();
    foreach (dungeonCell dcValue in dc)
    {
        int xi = dcValue.coord.x;
        int yi = dcValue.coord.y;
        int routeLeni = dcValue.routeLen;
        for (int u = 0; u < 4; u++)
        {
            if (lab[xi, yi].walls[u] == false && lab[xi + delta[u, 0], yi + delta[u, 1]].routeLen < 0)
            {
                lab[xi + delta[u, 0], yi + delta[u, 1]].prevCell = lab[xi, yi];
                if (lab[xi + delta[u, 0], yi + delta[u, 1]].routeLen == -1) lab[xi + delta[u, 0], yi + delta[u, 1]].routeLen++;
                lab[xi + delta[u, 0], yi + delta[u, 1]].routeLen += 1 + lab[xi + delta[u, 0], yi + delta[u, 1]].prevCell.routeLen;
                tempDc.Add(lab[xi + delta[u, 0], yi + delta[u, 1]]);
                turtles[currTurtle] = new Turtles(lab[xi + delta[u, 0], yi + delta[u, 1]], currTurtle);
                lab[xi + delta[u, 0], yi + delta[u, 1]].turtle = turtles[currTurtle];
                currTurtle++;
            }
        }
    }
    dc = tempDc;
}
Stopwatch sw = new Stopwatch();
sw.Restart();
List<Turn> resultCommands = new List<Turn>();
List<Turn> commands = new List<Turn>();
currTurtle = 0;
while (currTurtle < turtles.Length)
{
    commands = FindPath(turtles[currTurtle]);
    ApplyCommands(commands);
    resultCommands.AddRange(commands);
}
Console.WriteLine("Time find = {0}", sw.ElapsedMilliseconds);
Console.WriteLine("Commands = {0}", resultCommands.Count);
TestCommands();
Console.WriteLine("Time test = {0}", sw.ElapsedMilliseconds);
void ApplyCommands(List<Turn> commands)
{
    for (int currT = currTurtle; currT < turtles.Length; currT++)
    {
        Cell old_coord = turtles[currT].cell.coord;
        int old_id = turtles[currT].id;
        foreach (var c in commands)
        {
            int u = DecodeTurn(c);
            if (turtles[currT].cell.walls[u]) continue; // {{0, -1}, {1, 0}, {0, 1}, {-1, 0}};
            if (lab[turtles[currT].cell.coord.x + delta[u, 0], turtles[currT].cell.coord.y + delta[u, 1]].ct == cellType.exit)
            {
                //exit
                if (currT != currTurtle)
                {
                    turtles[currT] = turtles[currTurtle];
                    turtles[currT].id = currT;
                    old_id = currT;
                }
                if (lab[old_coord.x, old_coord.y].turtle != null && lab[old_coord.x, old_coord.y].turtle.id == turtles[currT].id)
                    lab[old_coord.x, old_coord.y].turtle = null;
                currTurtle++;
                goto exit;
            }
            turtles[currT].cell = lab[turtles[currT].cell.coord.x + delta[u, 0], turtles[currT].cell.coord.y + delta[u, 1]];
        }
    if (lab[old_coord.x, old_coord.y].turtle != null && lab[old_coord.x, old_coord.y].turtle.id == turtles[currT].id &&
      (old_coord.x != turtles[currT].cell.coord.x || old_coord.y != turtles[currT].cell.coord.y))
    lab[old_coord.x, old_coord.y].turtle = null;

    exit:;
        if (old_id == turtles[currT].id && currT >= currTurtle)
        {
            if (turtles[currT].cell.turtle != null && turtles[currT].id > turtles[currT].cell.turtle.id)
            {
                if (currT != currTurtle)
                {
                    turtles[currT] = turtles[currTurtle];
                    turtles[currT].id = currT;
                }
                currTurtle++;
            }
            else
            {
                turtles[currT].cell.turtle = turtles[currT];
            }
        }
    }
}
int DecodeTurn(Turn t)
{
    switch (t)
    {
        case Turn.up: return 0;
        case Turn.right: return 1;
        case Turn.down: return 2;
        default: return 3;
    }
}
List<Turn> FindPath(Turtles t)
{
    var result = new List<Turn>();
    dungeonCell startDc = t.cell;
    result.Add(decodeOneCommand(startDc));
    startDc = startDc.prevCell;
    while (startDc.ct != cellType.exit)
    {
        result.Add(decodeOneCommand(startDc));
        startDc = startDc.prevCell;
    }
    return result;
}
Turn decodeOneCommand(dungeonCell dc)
{
    if (dc.coord.x == dc.prevCell.coord.x) // up or down
    {
        if (dc.coord.y < dc.prevCell.coord.y) // down
            return Turn.down;
        return Turn.up;
    }
    else // left or right
    {
        if (dc.coord.x < dc.prevCell.coord.x) // right
            return Turn.right;
        return Turn.left;
    }
}
void TestCommands()
{
    for (int y = 0; y < Ysize; y++)
    {
        for (int x = 0; x < Xsize; x++)
        {
            if (lab[x, y].ct == cellType.empty)
            {
                ApplyTestCommands(resultCommands, x, y);
            }
        }
    }

}
void ApplyTestCommands(List<Turn> commands, int x, int y)
{
    foreach (var c in commands)
    {
        int u = DecodeTurn(c);
        if (lab[x, y].walls[u]) continue;
        if (lab[x + delta[u, 0], y + delta[u, 1]].ct == cellType.exit)
            return;
        x += delta[u, 0];
        y += delta[u, 1];
    }
    Console.ForegroundColor = ConsoleColor.DarkRed;
    Console.WriteLine("!!! ERROR !!!");
    Console.ResetColor();
}
public record Cell(int x, int y);
public enum Turn { up = 0, right = 1, down = 2, left = 3 };
public enum cellType { exit = -1, empty = 0, wall = 9 };
public class Turtles
{
    public int id { get; set; }
    public dungeonCell cell { get; set; }
    public Turtles(dungeonCell c, int id)
    {
        cell = c;
        this.id = id;
    }
}
public class dungeonCell
{
    public Turtles turtle { get; set; }
    public Cell coord { get; set; }
    public cellType ct { get; set; }
    public int routeLen { get; set; }
    public bool[] walls { get; set; }
    public dungeonCell prevCell { get; set; }
    public List<Turn> turns { get; set; }
    public dungeonCell(Cell c, cellType ct2, int rl, dungeonCell nc, bool[] w, List<Turn> t, Turtles tu)
    {
        coord = c;
        ct = ct2;
        routeLen = rl;
        prevCell = nc;
        walls = w;
        turns = t;
        turtle = tu;
    }
};